<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';
import { RpcEvent,type BusinessView,type InventoryView,type MarketplaceBidResult,type MarketplaceHistoryView,type MarketplaceListingType,type MarketplaceListingView,type MarketplaceObjectType,type MarketplacePurchaseResult,type MarketplaceSort,type PropertyOwnedView,type VehicleView } from '@eclipse/shared';
import { rpc } from '../core/rpc';
type Mode='market'|'mine'|'create'|'history';const mode=ref<Mode>('market'),listings=ref<MarketplaceListingView[]>([]),mine=ref<MarketplaceListingView[]>([]),history=ref<MarketplaceHistoryView[]>([]),cars=ref<VehicleView[]>([]),properties=ref<PropertyOwnedView[]>([]),businesses=ref<BusinessView[]>([]),inventory=ref<InventoryView|null>(null),busy=ref(false),error=ref(''),notice=ref('');
const objectType=ref<MarketplaceObjectType>('vehicle'),objectId=ref(''),price=ref(''),quantity=ref('1'),listingType=ref<MarketplaceListingType>('fixed'),durationHours=ref('24');const search=ref(''),filterType=ref<'all'|MarketplaceObjectType>('all'),filterListing=ref<'all'|MarketplaceListingType>('all'),minPrice=ref(''),maxPrice=ref(''),sort=ref<MarketplaceSort>('newest'),bids=ref<Record<string,string>>({});
const money=(v:string|null)=>Number(v??0).toLocaleString('ru-RU',{maximumFractionDigits:2});const typeName=(t:MarketplaceObjectType)=>({vehicle:'Транспорт',property:'Недвижимость',business:'Бизнес',item:'Предмет'}[t]);
const options=computed(()=>objectType.value==='vehicle'?cars.value.map(x=>({id:x.id,label:`${x.model} · ${x.plate??x.vin}`,blocked:x.spawned||x.impounded,max:1})):objectType.value==='property'?properties.value.filter(x=>x.ownedByMe).map(x=>({id:x.id,label:x.name,blocked:false,max:1})):objectType.value==='business'?businesses.value.map(x=>({id:x.id,label:x.name,blocked:false,max:1})):(inventory.value?.items??[]).map(x=>({id:x.id,label:`${x.name} ×${x.quantity}`,blocked:false,max:x.quantity})));
const load=async()=>{const filter={query:search.value,objectType:filterType.value,listingType:filterListing.value,minPrice:minPrice.value,maxPrice:maxPrice.value,sort:sort.value,limit:200};const[l,m,h,v,p,b,i]=await Promise.all([rpc<MarketplaceListingView[]>(RpcEvent.MarketList,filter),rpc<MarketplaceListingView[]>(RpcEvent.MarketMine),rpc<MarketplaceHistoryView[]>(RpcEvent.MarketHistory),rpc<VehicleView[]>(RpcEvent.VehicleList),rpc<PropertyOwnedView[]>(RpcEvent.PropertyOwned),rpc<BusinessView[]>(RpcEvent.BusinessOwned),rpc<InventoryView>(RpcEvent.InventoryGet)]);if(l.ok)listings.value=l.data;if(m.ok)mine.value=m.data;if(h.ok)history.value=h.data;if(v.ok)cars.value=v.data;if(p.ok)properties.value=p.data;if(b.ok)businesses.value=b.data;if(i.ok)inventory.value=i.data;};
const run=async<T>(event:string,payload:unknown,msg:string):Promise<T|null>=>{if(busy.value)return null;busy.value=true;error.value='';notice.value='';try{const r=await rpc<T>(event,payload);if(!r.ok){error.value=r.code;return null;}notice.value=msg;return r.data;}finally{busy.value=false;}};
const create=async()=>{if(!objectId.value||!price.value)return;const payload={objectType:objectType.value,objectId:objectId.value,title:'',price:price.value,listingType:listingType.value,quantity:objectType.value==='item'?Number(quantity.value):1,durationHours:Number(durationHours.value)};if(await run<MarketplaceListingView>(RpcEvent.MarketCreate,payload,'Объявление опубликовано')){objectId.value='';price.value='';mode.value='mine';await load();}};const cancel=async(id:string)=>{if(await run<MarketplaceListingView>(RpcEvent.MarketCancel,{listingId:id},'Объявление снято'))await load();};const buy=async(id:string)=>{if(await run<MarketplacePurchaseResult>(RpcEvent.MarketBuy,{listingId:id},'Покупка завершена'))await load();};const bid=async(id:string)=>{const amount=bids.value[id]??'';if(await run<MarketplaceBidResult>(RpcEvent.MarketBid,{listingId:id,amount},'Ставка принята')){bids.value[id]='';await load();}};const effective=(l:MarketplaceListingView)=>l.currentBid??l.price;const ends=(l:MarketplaceListingView)=>new Date(l.auctionEndsAt??l.expiresAt).toLocaleString('ru-RU');onMounted(()=>void load());
</script>
<template><section class="market"><div class="toolbar"><div><button :class="{active:mode==='market'}" @click="mode='market'">V‑Market</button><button :class="{active:mode==='mine'}" @click="mode='mine'">Мои объявления</button><button :class="{active:mode==='create'}" @click="mode='create'">Продать</button><button :class="{active:mode==='history'}" @click="mode='history'">История</button></div><button @click="load">Обновить</button></div><p v-if="error" class="msg error">{{error}}</p><p v-if="notice" class="msg ok">{{notice}}</p>
<div v-if="mode==='market'" class="filters"><input v-model="search" placeholder="Поиск"><select v-model="filterType"><option value="all">Все категории</option><option value="vehicle">Транспорт</option><option value="property">Недвижимость</option><option value="business">Бизнес</option><option value="item">Предметы</option></select><select v-model="filterListing"><option value="all">Все типы</option><option value="fixed">Фикс. цена</option><option value="auction">Аукцион</option></select><input v-model="minPrice" placeholder="Цена от"><input v-model="maxPrice" placeholder="Цена до"><select v-model="sort"><option value="newest">Сначала новые</option><option value="price_asc">Сначала дешевле</option><option value="price_desc">Сначала дороже</option><option value="ending">Скоро завершатся</option></select><button @click="load">Найти</button></div>
<div v-if="mode==='create'" class="create"><h3>Новое объявление</h3><label>Категория<select v-model="objectType" @change="objectId='' "><option value="vehicle">Транспорт</option><option value="property">Недвижимость</option><option value="business">Бизнес</option><option value="item">Предмет</option></select></label><label>Объект<select v-model="objectId"><option value="">Выберите объект</option><option v-for="o in options" :key="o.id" :value="o.id" :disabled="o.blocked">{{o.label}}</option></select></label><label v-if="objectType==='item'">Количество<input v-model="quantity" type="number" min="1"></label><label>Формат<select v-model="listingType"><option value="fixed">Продажа</option><option value="auction">Аукцион</option></select></label><label>{{listingType==='auction'?'Стартовая цена':'Цена'}}<input v-model="price" inputmode="decimal"></label><label>Срок, часов<input v-model="durationHours" type="number" min="1" max="168"></label><button :disabled="busy||!objectId||!price" @click="create">Опубликовать</button><small>Комиссия при успешной сделке: 5%. Предмет резервируется сервером сразу после публикации.</small></div>
<div v-else-if="mode==='history'" class="history"><article v-for="h in history" :key="h.id"><div><b>{{h.title}}</b><small>{{typeName(h.objectType)}} · {{h.kind}}</small></div><strong>${{money(h.amount)}}</strong><time>{{new Date(h.createdAt).toLocaleString('ru-RU')}}</time></article><p v-if="!history.length" class="empty">История пока пуста.</p></div>
<div v-else class="grid"><article v-for="l in (mode==='mine'?mine:listings)" :key="l.id"><div class="head"><div><small>{{typeName(l.objectType)}} · {{l.listingType==='auction'?'АУКЦИОН':'ПРОДАЖА'}}</small><h3>{{l.title}}<span v-if="l.quantity>1"> ×{{l.quantity}}</span></h3></div><strong>${{money(effective(l))}}</strong></div><p>До {{ends(l)}}<span v-if="l.currentBid"> · текущая ставка</span></p><div class="actions"><template v-if="mode==='market'&&!l.ownedByMe"><button v-if="l.listingType==='fixed'" :disabled="busy" @click="buy(l.id)">Купить</button><template v-else><input v-model="bids[l.id]" placeholder="Ваша ставка"><button :disabled="busy" @click="bid(l.id)">Ставка</button></template></template><span v-else-if="mode==='market'">Ваше объявление</span><button v-if="mode==='mine'&&l.status==='active'" class="danger" :disabled="busy" @click="cancel(l.id)">Снять</button><span v-if="mode==='mine'&&l.status!=='active'">{{l.status==='sold'?'Продано':'Снято'}}</span></div></article><p v-if="!(mode==='mine'?mine:listings).length" class="empty">Объявлений нет.</p></div></section></template>
<style scoped>.market{display:grid;gap:14px}.toolbar,.toolbar>div,.filters,.actions{display:flex;gap:7px;align-items:center}.toolbar{justify-content:space-between}.filters{flex-wrap:wrap}.filters input,.filters select,.create select,.create input,.actions input{border:1px solid var(--e-border);border-radius:9px;background:var(--e-surface-2);color:var(--e-text-primary);padding:9px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}article,.create{padding:16px;border:1px solid var(--e-border);border-radius:14px;background:var(--e-surface-1)}.head{display:flex;justify-content:space-between;gap:15px}.head h3{margin:4px 0}.head small{color:var(--e-accent)}p,small,span,time{color:var(--e-text-muted);font-size:12px}button{border:1px solid var(--e-border);border-radius:9px;background:var(--e-surface-2);color:var(--e-text-primary);padding:9px 12px;cursor:pointer}button.active{border-color:var(--e-accent)}button:disabled{opacity:.45}.danger,.error{color:#ff8585}.create{max-width:650px;display:grid;gap:10px}.create label{display:grid;gap:5px;color:var(--e-text-muted);font-size:12px}.history{display:grid;gap:7px}.history article{display:grid;grid-template-columns:1fr auto auto;gap:14px;align-items:center}.history article div{display:grid}.msg{padding:9px 12px;border-radius:9px}.ok{color:#7dde9f}.empty{grid-column:1/-1;text-align:center;padding:25px}</style>